UPDATE b_sk_token
SET remaining = remaining - 1
WHERE ride_date = #{rideDate}
  AND train_code = #{trainCode}
  AND remaining > 0

UPDATE b_sk_token
SET total_count = total_count + #{step},
    remaining   = remaining + #{step}
WHERE ride_date = #{rideDate}
  AND train_code = #{trainCode}
